            'L 120 10 ' +
            'Q 150 10 150 40 ' +
            'L 150 80 ' +
            'Q 150 110 120 110 ' +
            'L 55 110 ' +
            'Q 25 110 25 80 ' +
            'L 25 75 ' +
            'L 3 60 ' +
            'L 25 45 ' +
