            'L 120 10 ' +
            'Q 150 10 150 40 ' +
            'L 150 80 ' +
            'Q 150 110 120 110 ' +
            'L 55 110 ' +
            'Q 25 110 25 80 ' +
            'L 25 75 ' +
            'L 3 60 ' +
            'L 25 45 ' +
            'L 25 40 ' +
            'Q 25 10 55 10 Z" ' +
            'fill="none" ' +
            'stroke="' + color + '" ' +
