@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
 nrList=[["🌊连载🌊","2"],["🌊完结🌊","1"]]
	arList=["全部","长条","大女主","百合","耽美","纯爱","後宫","韩漫","奇幻","轻小说","生活","悬疑","格斗","搞笑","伪娘","竞技","职场","萌系","冒险","治愈","都市","霸总","神鬼","侦探","爱情","古风","欢乐向","科幻","穿越","性转换","校园","美食","悬疑","剧情","热血","节操","励志","异世界","历史","战争","恐怖","霸总"]
	nrList.map(([teg,uri])=>{
		push(teg,null,1,1)
	arList.map((tag)=>{
		url=`/api/comic/index/lists,{
 "body": "area=9&tags=${tag}&full=${uri}&page={{page}}",
 "method": "POST"
}`;
		push(tag, url, 1, 0.25);
		});
		});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

