.reading-content@html@js:
var html = result;
var urls = html.match(/data-manga-src="([^"]+)"/g);
var out = '';
var ref = JSON.stringify({headers: {Referer: 'https://baka3.me/'}});
if (urls) {
    for (var i = 0; i < urls.length; i++) {
        var u = urls[i].replace('data-manga-src="', '').replace('"', '');
        out += '<img src="' + u + ',' + ref + '"><br>';
    }
}
out;

